<script setup lang="ts">
import { ref,onMounted } from "vue";import { currentUser } from "../../state/auth";import { listUsers,createUser,deleteUser,setUserAdmin,signOutAllUsers } from "../../services/admin";import ToggleButton from "./ToggleButton.vue";import type { AdminUser } from "../../services/admin";
const users=ref<AdminUser[]>([]),loading=ref(true),error=ref<string|null>(null),signingOut=ref(false),signOutMessage=ref<string|null>(null);
async function loadUsers(){loading.value=true;error.value=null;try{users.value=await listUsers()}catch(err){error.value=err instanceof Error?err.message:"Failed to load users"}finally{loading.value=false}}onMounted(loadUsers);
async function signOutEveryone(){if(!window.confirm("Sign out every active session on this server, including your own? You will need to sign in again."))return;signingOut.value=true;signOutMessage.value=null;try{const result=await signOutAllUsers();signOutMessage.value=`Revoked ${result.sessions_revoked} active session${result.sessions_revoked===1?"":"s"}. Everyone must sign in again.`}catch(err){error.value=err instanceof Error?err.message:"Failed to sign out all users"}finally{signingOut.value=false}}
const showCreateForm=ref(false),newUsername=ref(""),newEmail=ref(""),newPassword=ref(""),newIsAdmin=ref(false),creating=ref(false),createError=ref<string|null>(null);
async function handleCreateUser(){creating.value=true;createError.value=null;try{await createUser({username:newUsername.value.trim(),email:newEmail.value.trim(),password:newPassword.value,isAdmin:newIsAdmin.value});newUsername.value="";newEmail.value="";newPassword.value="";newIsAdmin.value=false;showCreateForm.value=false;await loadUsers()}catch(err){createError.value=err instanceof Error?err.message:"Failed to create user"}finally{creating.value=false}}
const deletingUser=ref<AdminUser|null>(null),deleting=ref(false),deleteError=ref<string|null>(null);async function confirmDeleteUser(){if(!deletingUser.value)return;deleting.value=true;deleteError.value=null;try{await deleteUser(deletingUser.value.id);deletingUser.value=null;await loadUsers()}catch(err){deleteError.value=err instanceof Error?err.message:"Failed to delete user"}finally{deleting.value=false}}
const togglingAdminId=ref<string|null>(null);async function toggleAdmin(user:AdminUser){togglingAdminId.value=user.id;try{const updated=await setUserAdmin(user.id,!user.is_admin);const index=users.value.findIndex(u=>u.id===user.id);if(index!==-1)users.value[index]=updated}catch(err){error.value=err instanceof Error?err.message:"Failed to update user"}finally{togglingAdminId.value=null}}
function openCreateForm(){newUsername.value="";newEmail.value="";newPassword.value="";newIsAdmin.value=false;createError.value=null;showCreateForm.value=true}
</script>
<template><section class="settings-section"><h2>Users</h2><p class="section-hint">Manage the accounts on this server, including administrator access.</p><div class="security-panel"><div><h3>Session management</h3><p>Immediately invalidate every active login session. This includes your current session; the page will remain visible until you choose to sign in again.</p></div><button type="button" class="danger-button" :disabled="signingOut" @click="signOutEveryone">{{ signingOut?"Signing out…":"Sign out all users" }}</button></div><p v-if="signOutMessage" class="form-success">{{ signOutMessage }}</p><p v-if="loading">Loading…</p><p v-else-if="error" class="form-error">{{ error }}</p><template v-else><table class="user-table"><thead><tr><th>Username</th><th>Email</th><th>Role</th><th>Joined</th><th></th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td>{{ user.username }}</td><td>{{ user.email }}</td><td><span class="role-badge" :class="{admin:user.is_admin}">{{ user.is_admin?"Admin":"User" }}</span></td><td class="joined">{{ user.created_at?new Date(user.created_at*1000).toLocaleDateString():"N/A" }}</td><td class="actions"><button type="button" class="small-button" :disabled="user.id===currentUser?.id||togglingAdminId===user.id" @click="toggleAdmin(user)">{{ user.is_admin?"Demote":"Promote" }}</button><button type="button" class="small-button danger" :disabled="user.id===currentUser?.id" @click="deletingUser=user;deleteError=null">Delete</button></td></tr></tbody></table><button type="button" class="secondary-button" @click="showCreateForm?showCreateForm=false:openCreateForm()">{{ showCreateForm?"Cancel":"+ Create user" }}</button><form v-if="showCreateForm" class="create-form" @submit.prevent="handleCreateUser"><label class="field"><span>Username</span><input v-model="newUsername" type="text" required /></label><label class="field"><span>Email</span><input v-model="newEmail" type="email" required /></label><label class="field"><span>Password</span><input v-model="newPassword" type="password" required autocomplete="new-password" /></label><ToggleButton v-model="newIsAdmin" label="Grant admin access">Grant admin access</ToggleButton><div v-if="createError" class="form-error">{{ createError }}</div><button type="submit" class="primary-button" :disabled="creating">{{ creating?"Creating…":"Create user" }}</button></form></template><div v-if="deletingUser" class="confirm-backdrop" @click.self="deletingUser=null"><div class="confirm-dialog"><h3>Delete {{ deletingUser.username }}?</h3><p>This can't be undone: their data folder is removed too.</p><div v-if="deleteError" class="form-error">{{ deleteError }}</div><div class="confirm-actions"><button type="button" class="secondary-button" @click="deletingUser=null">Cancel</button><button type="button" class="danger-button" :disabled="deleting" @click="confirmDeleteUser">{{ deleting?"Deleting…":"Delete" }}</button></div></div></div></section></template>
<style scoped>.settings-section h2{margin:0 0 8px;padding-left:12px;border-left:3px solid #d68a34;font-size:1rem;color:#fff}.section-hint{color:#999;font-size:.82rem;line-height:1.6;margin:0 0 16px}.security-panel{display:flex;justify-content:space-between;align-items:center;gap:18px;background:rgba(220,38,38,.06);border:1px solid rgba(220,38,38,.25);border-radius:10px;padding:15px;margin-bottom:16px}.security-panel h3{margin:0 0 5px;color:#fff;font-size:.9rem}.security-panel p{margin:0;color:#999;font-size:.8rem;line-height:1.5}.user-table{width:100%;border-collapse:collapse;margin-bottom:16px;font-size:.85rem}.user-table th{text-align:left;color:#777;font-size:.72rem;text-transform:uppercase;padding:0 10px 8px;border-bottom:1px solid #2a2a2a}.user-table td{padding:10px;border-bottom:1px solid #232323;color:#ccc}.role-badge{font-size:11px;font-weight:700;padding:3px 10px;border-radius:999px;color:#999;background:rgba(255,255,255,.06)}.role-badge.admin{color:#d68a34;background:rgba(214,138,52,.14)}.joined{color:#999;font-size:.8rem}.actions{display:flex;gap:6px}.small-button,.secondary-button{background:rgba(255,255,255,.08);color:#fff;border:0;border-radius:6px;padding:6px 10px;font-size:12px;font-weight:600;cursor:pointer}.small-button:disabled,.danger-button:disabled{opacity:.4;cursor:not-allowed}.small-button.danger{color:#fca5a5}.secondary-button{border-radius:8px;padding:10px 18px}.create-form{display:flex;flex-direction:column;gap:14px;margin-top:16px;padding-top:16px;border-top:1px solid #2a2a2a}.field{display:flex;flex-direction:column;gap:6px;font-size:.85rem;color:#ccc}.field input{background:#111;border:1px solid #3a3a3a;border-radius:8px;color:#fff;padding:10px 12px;font:inherit}.primary-button{background:#d68a34;color:#111;border:0;border-radius:8px;padding:11px;font-weight:600;cursor:pointer}.primary-button:disabled{opacity:.6}.form-error,.form-success{font-size:13px;border-radius:8px;padding:8px 10px}.form-error{color:#fca5a5;background:rgba(220,38,38,.1);border:1px solid rgba(220,38,38,.3)}.form-success{color:#86efac;background:rgba(34,197,94,.1);border:1px solid rgba(34,197,94,.3)}.danger-button{background:rgba(220,38,38,.18);color:#fca5a5;border:0;border-radius:8px;padding:10px 14px;font-weight:600;cursor:pointer}.confirm-backdrop{position:fixed;inset:0;background:rgba(0,0,0,.65);display:flex;align-items:center;justify-content:center;z-index:60}.confirm-dialog{background:#1a1a1a;border:1px solid #2a2a2a;border-radius:12px;padding:22px;max-width:360px;box-shadow:0 24px 64px rgba(0,0,0,.6)}.confirm-dialog h3{margin:0 0 8px;color:#fff}.confirm-dialog p{margin:0 0 18px;color:#999;font-size:.85rem}.confirm-actions{display:flex;justify-content:flex-end;gap:10px}</style>